<script lang="ts">let chartLibrary:Promise<void>|undefined;function loadChart(){return chartLibrary??=new Promise<void>((resolve,reject)=>{const script=document.createElement('script');script.src='/pms-assets/vendor/apexcharts.js';script.onload=()=>resolve();script.onerror=()=>{chartLibrary=undefined;reject(Error('Unable to load chart library.'));};document.head.appendChild(script);});}</script>
<script setup lang="ts">import {ref,onMounted,onUnmounted,watch} from 'vue';const props=defineProps<{kind:string;data:{labels:string[];series:number[]}}>();const host=ref<HTMLElement|null>(null),error=ref('');let chart:any,observer:MutationObserver|undefined,disposed=false;async function render(){if(disposed||!host.value)return;await loadChart();if(disposed)return;chart?.destroy();const workspace=host.value!.closest('.pms-workspace')!,style=getComputedStyle(workspace),dark=workspace.classList.contains('pms-dark'),muted=style.getPropertyValue('--pms-muted').trim(),text=style.getPropertyValue('--pms-text').trim(),border=style.getPropertyValue('--pms-border').trim();const options:any={chart:{type:props.kind==='projects'?'donut':'bar',height:285,background:'transparent',toolbar:{show:false}},series:props.kind==='projects'?props.data.series:[{name:'Tasks',data:props.data.series}],colors:props.kind==='projects'?['#f59e0b','#635bff','#16a86b','#0ea5e9','#ef4444']:['#635bff'],dataLabels:{enabled:false},tooltip:{theme:dark?'dark':'light'},noData:{text:'No data',style:{color:muted}}};if(props.kind==='projects')Object.assign(options,{labels:props.data.labels,stroke:{width:3,colors:[dark?'#171a24':'#fff']},legend:{position:'bottom',fontSize:'12px',labels:{colors:muted}},plotOptions:{pie:{donut:{size:'72%',labels:{show:true,name:{color:muted},value:{color:text,fontSize:'24px',fontWeight:700},total:{show:true,label:'Total projects',color:muted,formatter:(w:any)=>w.globals.seriesTotals.reduce((a:number,b:number)=>a+b,0)}}}}}});else Object.assign(options,{plotOptions:{bar:{borderRadius:7,columnWidth:'48%',distributed:true}},legend:{show:false},grid:{borderColor:border,strokeDashArray:4},xaxis:{categories:props.data.labels,labels:{style:{colors:muted,fontSize:'12px'}},axisBorder:{color:border},axisTicks:{show:false}},yaxis:{min:0,forceNiceScale:true,labels:{style:{colors:[muted]},formatter:(v:number)=>Number.isInteger(v)?v:''}}});if(props.kind==='workload')Object.assign(options,{series:[{name:'Open tasks',data:props.data.series}],colors:['#0ea5e9'],plotOptions:{bar:{horizontal:true,borderRadius:6,barHeight:'52%',dataLabels:{position:'top'}}},dataLabels:{enabled:true,offsetX:8,style:{colors:[text],fontWeight:700}},xaxis:{categories:props.data.labels,min:0,forceNiceScale:true,labels:{style:{colors:muted}},axisBorder:{color:border},axisTicks:{show:false}},yaxis:{labels:{style:{colors:[muted],fontSize:'12px'},maxWidth:130}},noData:{text:'No assigned open tasks',style:{color:muted}}});chart=new (window as any).ApexCharts(host.value,options);await chart.render();}onMounted(()=>{void render().catch(e=>error.value=e.message);observer=new MutationObserver(()=>void render().catch(e=>error.value=e.message));observer.observe(host.value!.closest('.pms-workspace')!,{attributes:true,attributeFilter:['class']});});watch(()=>props.data,()=>void render().catch(e=>error.value=e.message));onUnmounted(()=>{disposed=true;observer?.disconnect();chart?.destroy();});</script><template><div ref="host" class="dashboard-chart"></div><p v-if="error" role="alert">{{error}}</p></template>